// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import {IWhitelist} from "../Whitelist/IWhitelist.sol";
import {IAssetsForwarderEvents} from "./IAssetsForwarderEvents.sol";
import {IAssetsForwarderErrors} from "./IAssetsForwarderErrors.sol";

/**
 * @title IAssetsForwarder
 * @notice Interface for the AssetsForwarder contract
 */
interface IAssetsForwarder is
    IWhitelist,
    IAssetsForwarderEvents,
    IAssetsForwarderErrors
{
    /**
     * @notice Pulls assets from the caller and sends them to the target address
     * @param targetAddress The address to receive the assets
     * @param asset The address of the asset to transfer
     * @param amount The amount of assets to transfer
     */
    function forwardAsset(
        address targetAddress,
        address asset,
        uint256 amount
    ) external;

    /**
     * @notice Sends existing assets in the contract to the target address
     * @param targetAddress The address to receive the assets
     * @param asset The address of the asset to transfer
     * @param amount The amount of assets to transfer
     */
    function sendAsset(
        address targetAddress,
        address asset,
        uint256 amount
    ) external;

    /**
     * @notice Sends existing assets in the contract to the caller (keeper)
     * @param asset The address of the asset to sweep
     * @param amount The amount of assets to sweep
     */
    function sweepAsset(address asset, uint256 amount) external;
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

/**
 * @title IAssetsForwarderErrors
 * @notice Interface for the AssetsForwarder errors
 */
interface IAssetsForwarderErrors {
    /**
     * @notice Thrown when the specified target address is the zero address
     */
    error InvalidTargetAddress();

    /**
     * @notice Thrown when the specified asset is the zero address
     */
    error InvalidAssetAddress();

    /**
     * @notice Thrown when the specified amount is zero
     */
    error ZeroAmount();
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

/**
 * @title IAssetsForwarderEvents
 * @notice Interface for the AssetsForwarder events
 */
interface IAssetsForwarderEvents {
    /**
     * @notice Emitted when assets are forwarded from the sender to a target address
     * @param sender The address that initiated the forward and provided the assets
     * @param target The address that received the assets
     * @param asset The address of the asset transferred
     * @param amount The amount of assets transferred
     */
    event AssetForwarded(
        address indexed sender,
        address indexed target,
        address indexed asset,
        uint256 amount
    );

    /**
     * @notice Emitted when existing assets in the contract are sent to a target address
     * @param target The address that received the assets
     * @param asset The address of the asset transferred
     * @param amount The amount of assets transferred
     */
    event AssetSent(
        address indexed target,
        address indexed asset,
        uint256 amount
    );

    /**
     * @notice Emitted when existing assets in the contract are swept to the keeper
     * @param keeper The address of the keeper that received the assets
     * @param asset The address of the asset transferred
     * @param amount The amount of assets transferred
     */
    event AssetSwept(
        address indexed keeper,
        address indexed asset,
        uint256 amount
    );
}

